    {"id": "R17", "effect": "E15", "cond": "edit of the agent's own permission, hook, gate or instruction config: a path the CARD lists as the agent's own configuration (a .git/hooks path is never on that list, Q5)", "label": "BLOCK", "reason": "weaken_security", "tier": "hard", "tier_source": "hard_deny: removing the agent's own permission or hook config, disabling its own gate, instruction-poisoning style edits (excerpt item 5, auto-mode-config; " + PENDING + ")"},
